using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.FNZ.Cuotas;using GraphApi.Services.FNZ.Cuotas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.FNZ.Cuotas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Cuotas: creación, actualización y eliminación.")]    public class CuotasMutation    {        [Authorize]        [GraphQLName("createCuotas")]        [GraphQLDescription("Crea un nuevo Cuota usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadCuotas> CreateCuotasAsync(            [GraphQLDescription("Datos necesarios para crear el Cuota.")]            clCreateCuotas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Cuota.")]            ICuotasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateCuotas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateCuotas")]        [GraphQLDescription("Actualiza los campos especificados de un Cuota existente.")]        public async Task<clReadCuotas?> UpdateCuotasAsync(            [GraphQLDescription("Datos del Cuota a actualizar.")]            clUpdateCuotas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Cuota.")]            ICuotasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateCuotas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteCuotas")]        [GraphQLDescription("Elimina un Cuota por su ID.")]        public async Task<bool> delCuotasAsync(            [GraphQLDescription("ID del Cuota a eliminar.")]            int nCuotasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Cuota.")]            ICuotasService objService        )        {            return await objService.DeleteCuotas(nCuotasID);        }    }}